int main() {
    int t;
    cin >> t;
    while (t--) {
        int V, E;
        cin >> V >> E;
        vector<vector<int>> adj(V);
        for (int i = 0; i < E; i++) {
            int a, b; cin >> a >> b;
            adj[a].push_back(b);
            adj[b].push_back(a);
        }
        Solution s;
        cout << "isCycle = " << (s.isCycle(adj) ? "true" : "false") << endl;
    }
}

int main() {
    int n, m;
    cin >> n >> m;
    vector<vector<int>> grid(n, vector<int>(m));
    for (auto &row : grid)
        for (int &x : row) cin >> x;
    Solution *s = new Solution();
    cout << "findMaxFish = " << s->findMaxFish(grid) << endl;
}

